      "code": "#include <iostream>\n#include <vector>\n#include <cmath>\n#include <array>\n#include <iomanip>\n\nstruct alignas(64) BasketLegQuote {\n    uint32_t bidTicks;\n    uint32_t askTicks;\n    uint32_t bidSize;\n    uint32_t askSize;\n};\n\nstruct alignas(64) MultiLegSignal {\n    double spreadValue;\n    double zScore;\n    bool shouldEnter;\n    bool shouldExit;\n    char spreadDirection; // 'L' = Long spread, 'S' = Short spread, 'N' = Neutral\n};\n\nclass ProductionBasketArbEngine {\nprivate:\n    double m_spreadMean;\n    double m_spreadStdDev;\n    double m_entryZThreshold;\n    double m_exitZThreshold;\n    std::array<double, 3> m_betaWeights; // e.g. +1.0, -1.5, +0.5\n\npublic:\n    ProductionBasketArbEngine(\n        double mean,\n        double stdDev,\n        double entryZ,\n        double exitZ,\n        std::array<double, 3> weights)\n        : m_spreadMean(mean),\n          m_spreadStdDev(stdDev),\n          m_entryZThreshold(entryZ),\n          m_exitZThreshold(exitZ),\n          m_betaWeights(weights) {}\n\n    MultiLegSignal evaluateTick(const std::array<BasketLegQuote, 3>& quotes) {\n        // Calculate mid-prices\n        double mid0 = (quotes[0].bidTicks + quotes[0].askTicks) * 0.5 / 100.0;\n        double mid1 = (quotes[1].bidTicks + quotes[1].askTicks) * 0.5 / 100.0;\n        double mid2 = (quotes[2].bidTicks + quotes[2].askTicks) * 0.5 / 100.0;\n\n        // Compute instantaneous synthetic spread: S = beta0 * P0 + beta1 * P1 + beta2 * P2\n        double currentSpread = (m_betaWeights[0] * mid0) +\n                               (m_betaWeights[1] * mid1) +\n                               (m_betaWeights[2] * mid2);\n\n        double z = (currentSpread - m_spreadMean) / m_spreadStdDev;\n\n        bool enter = false;\n        bool exit = false;\n        char dir = 'N';\n\n        if (z >= m_entryZThreshold) {\n            enter = true;\n            dir = 'S'; // Spread is overpriced -> Short spread (sell leg 0, buy leg 1, sell leg 2)\n        } else if (z <= -m_entryZThreshold) {\n            enter = true;\n            dir = 'L'; // Spread is underpriced -> Long spread (buy leg 0, sell leg 1, buy leg 2)\n        } else if (std::fabs(z) <= m_exitZThreshold) {\n            exit = true;\n            dir = 'N';\n        }\n\n        return { currentSpread, z, enter, exit, dir };\n    }\n};\n\nint inspectProductionBasketArbitrage() {\n    // 3-Asset Cointegrated Basket: +1.0 A, -1.5 B, +0.5 C\n    std::array<double, 3> weights = { 1.0, -1.5, 0.5 };\n    double meanSpread = 5.00;\n    double stdSpread = 0.50;\n    double entryZ = 2.0; // Enter at |Z| >= 2.0\n    double exitZ = 0.2;  // Exit at |Z| <= 0.2\n\n    ProductionBasketArbEngine engine(meanSpread, stdSpread, entryZ, exitZ, weights);\n\n    // Simulate market quote states\n    struct MarketTick {\n        uint32_t step;\n        std::array<BasketLegQuote, 3> quotes;\n        const char* note;\n    };\n\n    std::vector<MarketTick> ticks = {\n        {1, {{ {10000, 10002, 100, 100}, {7000, 7002, 100, 100}, {2000, 2002, 100, 100} }}, \"Equilibrium State\"},\n        {2, {{ {10050, 10052, 100, 100}, {6950, 6952, 100, 100}, {2000, 2002, 100, 100} }}, \"Moderate Widening\"},\n        {3, {{ {10180, 10182, 100, 100}, {6880, 6882, 100, 100}, {2000, 2002, 100, 100} }}, \"Extreme Divergence (Z > 2.0)\"},\n        {4, {{ {10100, 10102, 100, 100}, {6940, 6942, 100, 100}, {2000, 2002, 100, 100} }}, \"Partial Mean Reversion\"},\n        {5, {{ {10000, 10002, 100, 100}, {7000, 7002, 100, 100}, {2000, 2002, 100, 100} }}, \"Full Reversion to Mean (Z = 0)\"}\n    };\n\n    std::cout << \"--- Production Cointegrated Basket Arbitrage Benchmark ---\\n\";\n    for (const auto& t : ticks) {\n        auto sig = engine.evaluateTick(t.quotes);\n        std::cout << \"Tick #\" << t.step \n                  << \" | Spread: $\" << std::fixed << std::setprecision(2) << sig.spreadValue\n                  << \" | Z: \" << std::showpos << sig.zScore << std::noshowpos\n                  << \" | Action: \";\n\n        if (sig.shouldEnter) {\n            std::cout << \">>> ENTER \" << (sig.spreadDirection == 'S' ? \"SHORT SPREAD\" : \"LONG SPREAD\") << \" <<<\";\n        } else if (sig.shouldExit) {\n            std::cout << \"--- CLOSE / LIQUIDATE SPREAD ---\";\n        } else {\n            std::cout << \"HOLD POSITION\";\n        }\n        std::cout << \" (\" << t.note << \")\\n\";\n    }\n\n    return 0;\n}\n\nint main() {\n    return inspectProductionBasketArbitrage();\n}",
